204	impl Rule for NoUnusedVars {
205	    fn from_configuration(value: serde_json::Value) -> Result<Self, serde_json::error::Error> {
206	        Ok(Self(Box::new(NoUnusedVarsOptions::try_from(value).unwrap_or_default())))
207	    }
208	
209	    fn run_once(&self, ctx: &LintContext) {
210	        for symbol in ctx.scoping().symbol_ids() {
211	            let symbol = Symbol::new(ctx, ctx.module_record(), symbol);
212	            if Self::should_skip_symbol(&symbol) {
213	                continue;
214	            }
215	
216	            self.run_on_symbol_internal(&symbol, ctx);
217	        }
218	    }
219	
220	    fn should_run(&self, ctx: &ContextHost) -> bool {
221	        // ignore .d.ts and vue/svelte/astro files.
222	        // 1. declarations have side effects (they get merged together)
223	        // 2. vue/svelte/astro scripts declare variables that get used in the template, which
224	        //    we can't detect
225	        !ctx.source_type().is_typescript_definition()
226	            && !ctx
227	                .file_extension()
228	                .is_some_and(|ext| ext == "vue" || ext == "svelte" || ext == "astro")
229	    }
