impl TryFrom<&Value> for NoUnusedVarsFixMode {
    type Error = OxcDiagnostic;

    fn try_from(value: &Value) -> Result<Self, Self::Error> {
        match value {
            Value::String(s) => match s.as_str() {
                "off" => Ok(Self::Off),
                "suggestion" => Ok(Self::Suggestion),
                "fix" => Ok(Self::Fix),
                s => Err(invalid_option_mismatch_error(
                    "fix",
                    ["off", "suggestion", "fix"],
                    s,
                )),
            },
            v => Err(invalid_option_error("fix", format!("Expected a string, got {v}"))),
        }
    }
}

